  function entries(kind){return Object.keys(db[kind]||{}).map(function(id){return Object.assign({id:id},db[kind][id]);});}
  function allVenues(){return db?db.venues||[]:[];}
  function venues(){return allVenues().filter(function(v){return (s.cities.length||s.venues.length)&&(!s.cities.length||s.cities.indexOf(v.city)>=0)&&(!s.venues.length||s.venues.indexOf(v.id)>=0);}).sort(function(a,b){return a.city.localeCompare(b.city,'ru')||a.name.localeCompare(b.name,'ru');});}
