  function input(name,value,type,extra){return '<input name="'+name+'" type="'+(type||'text')+'" value="'+esc0(value)+'" '+(extra||'')+'>';}
  function select(name,options,value){return '<select name="'+name+'">'+options.map(function(o){return '<option value="'+esc0(o[0])+'"'+(String(o[0])===String(value)?' selected':'')+'>'+esc0(o[1])+'</option>';}).join('')+'</select>';}
  function projectOptions(){return [['','Без проекта']].concat(Object.keys(WK.projects||{}).map(function(id){return [id,WK.projects[id].title];}));}
  function dateInput(name,value,optional){return input(name,value,'hidden')+button('date',esc0(value?fmt(value,{day:'numeric',month:'short',year:'numeric'}):'Выбрать дату'),'wkc-button','data-name="'+name+'"'+(optional?' data-optional="1"':''));}
  function load(){if(loading)return;loading=true;error='';apiJson('GET','/api/availability').then(function(x){if(!x.ok)throw new Error((x.d||{}).error||'Не удалось загрузить даты');db=x.d;idx=makeIndex(db);},function(){error='Нет связи с приложением';}).catch(function(e){error=e.message;}).then(function(){loading=false;if(S.view==='availability')render();});}
  function send(op,form,success){if(saving)return; saving=true;if(form){form.querySelectorAll('[type=submit]').forEach(function(b){b.disabled=true;});form.querySelector('.av-error').textContent='';}
    return apiJson('POST','/api/availability',op).then(function(x){if(!x.ok)throw new Error((x.d||{}).error||'Не удалось сохранить');db=x.d;idx=makeIndex(db);saving=false;if(form&&form.isConnected)$('pjDlg').close();if(success)success();if(S.view==='availability')render();toast('Сохранено');return true;}).catch(function(e){saving=false;if(form&&form.isConnected){form.querySelector('.av-error').textContent=e.message;form.querySelectorAll('[type=submit]').forEach(function(b){b.disabled=false;});}else toast(e.message);return false;});
  }
  function dialog(title,body,kind,id){var d=pjDialog('pj-edit av-dialog',title,'<form class="form-grid av-form" data-av-form="'+kind+'" data-id="'+(id||'')+'">'+body+'<div class="av-error err full" role="alert"></div><div class="form-actions full"><button class="btn-dark" type="submit">Сохранить</button>'+button('close','Отмена','btn-ghost')+'</div></form>');enhanceSelects(d);return d;}
  function venueInput(value){return field('Площадка',select('venue',allVenues().map(function(v){return [v.id,v.city+' · '+v.name];}),value),true);}
  function common(r){return field('Контакт площадки',input('contact',r.contact||'',null,'maxlength="300"'))+field('Кто уточнил',input('author',r.author||'',null,'maxlength="300"'))+field('Комментарий', '<textarea name="note" rows="3" maxlength="2000">'+esc0(r.note||'')+'</textarea>',true);}
  function reportForm(){var v=currentVenue();if(!v)return picker();dialog('Ответ площадки',venueInput(v.id)+field('Месяц',input('month',s.anchor.slice(0,7),'month','required'))+field('Когда получен ответ',dateInput('asof',wkDay(0)))+field('Полнота ответа',select('mode',[['full','Все свободные даты месяца'],['partial','Только названные даты']],'full'),true)+field('Свободные числа',input('free','',null,'placeholder="5, 8, 12–15" maxlength="150"'),true)+field('Занятые числа (для частичного ответа)',input('busy','',null,'placeholder="Например: 6, 9" maxlength="150"'),true)+'<p class="av-help full">Полный ответ: остальные дни месяца считаются занятыми. Пустой список свободных дат — свободных дат нет. Частичный ответ меняет только указанные числа.</p>'+common(v),'reports');}
  function bookingForm(id){var r=id?db.bookings[id]:{venue:(currentVenue()||{}).id,date:s.day,status:'hold',project:s.project,artist:s.artist},copy=Object.assign({},r);if(!r.venue)return picker();var d=dialog(id?'Резерв или бронь':'Зарезервировать дату',venueInput(r.venue)+field('Дата',dateInput('date',r.date))+field('Договорённость',select('status',[['hold','Наш резерв'],['confirmed','Подтверждённая бронь'],['cancelled','Резерв / бронь сняты']],r.status))+field('Артист / название проекта',input('artist',r.artist||'',null,'required maxlength="300" list="avArtists"'),true)+field('Рабочий проект',select('project',projectOptions(),r.project||''),true)+field('Подтвердить резерв до',dateInput('until',r.until||'',true),true)+'<p class="av-help full">Бронь подтверждается в разговоре с площадкой. Просроченный резерв остаётся занятым для наших проектов, пока вы не уточните или не снимете его.</p>'+common(r),'bookings',id);d.querySelector('form')._expected=id?copy:null;}
  function requestForm(id){var r=id?db.requests[id]:{artist:s.artist,project:s.project,status:'call'},v=currentVenue();if(!v)return picker();var body=id?venueInput(r.venue)+field('Месяц',input('month',r.month,'month','required')):'<p class="av-help full">План прозвона для '+venues().length+' выбранных площадок. Уже открытые запросы того же проекта не дублируются.</p>'+field('С месяца',input('from',s.anchor.slice(0,7),'month','required'))+field('По месяц включительно',input('to',monthShift(s.anchor.slice(0,7),s.count-1),'month','required'));
    var d=dialog(id?'Запрос дат':'Запланировать прозвон',body+field('Артист (необязательно)',input('artist',r.artist||'',null,'maxlength="300" list="avArtists"'),true)+field('Рабочий проект',select('project',projectOptions(),r.project||''),true)+field('Состояние',select('status',[['call','Нужно позвонить'],['waiting','Ждём ответа'],['answered','Ответ получен']],r.status))+field('Следующий звонок',dateInput('next',r.next||'',true))+common(r),'requests',id);d.querySelector('form')._expected=id?Object.assign({},r):null;}
  function picker(){var cities=Array.from(new Set(allVenues().map(function(v){return v.city;}).filter(Boolean))).sort(function(a,b){return a.localeCompare(b,'ru');});dialog('Города и площадки',field('С месяца',input('anchor',s.anchor.slice(0,7),'month','required'))+field('Месяцев в сводке',select('count',[[1,'1'],[3,'3'],[6,'6'],[12,'12']],String(s.count)))+'<label class="av-search full">Поиск '+input('search','',null,'placeholder="Город или площадка"')+'</label><div class="av-pick-cols full"><div><h3>Города</h3><div class="av-pick-list">'+cities.map(function(c){return '<label data-av-city-row><input type="checkbox" name="cities" value="'+esc0(c)+'"'+(s.cities.indexOf(c)>=0?' checked':'')+'>'+esc0(c)+'</label>';}).join('')+'</div></div><div><h3>Площадки</h3><p class="av-help">Не отмечены отдельные площадки — все площадки выбранных городов.</p><div class="av-pick-list">'+allVenues().map(function(v){return '<label data-av-venue-row data-city="'+esc0(v.city)+'"><input type="checkbox" name="venues" value="'+esc0(v.id)+'"'+(s.venues.indexOf(v.id)>=0?' checked':'')+'><span>'+esc0(v.name)+'<small>'+esc0(v.city)+'</small></span></label>';}).join('')+'</div></div></div>'+button('clear-filter','Снять выбор','pj-plain'),'filters');filterPicker();}
  function filterPicker(){var f=document.querySelector('[data-av-form="filters"]');if(!f)return;var q=f.elements.search.value.toLowerCase(),cities=Array.from(f.querySelectorAll('[name=cities]:checked')).map(function(e){return e.value;});f.querySelectorAll('[data-av-city-row]').forEach(function(r){r.hidden=!!q&&r.textContent.toLowerCase().indexOf(q)<0;});f.querySelectorAll('[data-av-venue-row]').forEach(function(r){r.hidden=(cities.length&&cities.indexOf(r.getAttribute('data-city'))<0)||(q&&r.textContent.toLowerCase().indexOf(q)<0);});}
  function months(){return Array.from({length:s.count},function(_,n){return monthShift(s.anchor.slice(0,7),n);});}
  function monthStats(v,ym){var states=Array.from({length:monthSize(ym)},function(_,i){return resolve(idx,v.id,ym+'-'+pad(i+1),wkDay(0));});return {free:states.map(function(x,i){return x.status==='free'?i+1:0;}).filter(Boolean),known:states.filter(function(x){return x.status!=='unknown'&&x.status!=='recheck';}).length,hold:states.filter(function(x){return x.status==='hold';}).length,confirmed:states.filter(function(x){return x.status==='confirmed';}).length,latest:(idx.reports[v.id+'|'+ym]||[])[0]};}
  function summary(list){var ms=months();return '<div class="av-summary"><div class="av-summary-head"><h2>Сведения по месяцам</h2><label>Месяцев '+select('count',[[1,'1'],[3,'3'],[6,'6'],[12,'12']],String(s.count))+'</label></div><div class="av-table-scroll"><table class="av-table"><thead><tr><th>Город · площадка</th>'+ms.map(function(m){return '<th>'+esc0(monthName(m))+'</th>';}).join('')+'</tr></thead><tbody>'+list.map(function(v){return '<tr><th>'+esc0(v.city)+'<small>'+esc0(v.name)+'</small></th>'+ms.map(function(m){var z=monthStats(v,m);return '<td>'+button('month-cell','<b>'+ (z.free.length?z.free.length+' свободно':!z.known?'Нет данных':z.known===monthSize(m)?'Нет свободных':'Нет свободных в ответе')+'</b><small>'+ (z.known===0?'Нет данных':z.known<monthSize(m)?'Частично: '+z.known+' из '+monthSize(m):'Месяц проверен')+'</small>'+(z.free.length?'<span>'+z.free.slice(0,10).join(', ')+(z.free.length>10?'…':'')+'</span>':'')+(z.hold||z.confirmed?'<small>Резерв '+z.hold+' · бронь '+z.confirmed+'</small>':'')+(z.latest?'<small>Ответ '+esc0(fmt(z.latest.asof))+'</small>':''),'av-monthcell','data-venue="'+v.id+'" data-month="'+m+'"')+'</td>';}).join('')+'</tr>';}).join('')+'</tbody></table></div></div>';}
  function calendarGrid(list){var days=WorkCalendarDates.monthDays(s.anchor,s.view==='week'),weekdays=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'];return '<div class="wkc-content'+(s.view==='week'?' wkc-week':'')+'"><div class="wkc-weekdays">'+weekdays.map(function(d){return '<span>'+d+'</span>';}).join('')+'</div><div class="wkc-grid" role="group" aria-label="Календарь площадок">'+days.map(function(day){var rows=list.map(function(v){return {v:v,x:resolve(idx,v.id,day,wkDay(0))};}),shown=rows.filter(function(r){return list.length===1||['free','hold','confirmed','recheck'].indexOf(r.x.status)>=0;}),weekend=new Date(day+'T12:00:00').getDay()%6===0;
      return '<div class="wkc-day'+(shown.length?' has-events':'')+(day.slice(0,7)!==s.anchor.slice(0,7)?' outside':'')+(weekend?' weekend':'')+(s.day===day?' selected':'')+(day===wkDay(0)?' today':'')+'">'+button('day','','wkc-daypick','data-day="'+day+'" aria-label="'+esc0(fmt(day,{day:'numeric',month:'long',year:'numeric'}))+'" aria-pressed="'+(s.day===day)+'"')+'<span class="wkc-daynum">'+ +day.slice(8)+'</span><div class="wkc-events">'+shown.slice(0,s.view==='week'?5:3).map(function(r){return button('slot',esc0((list.length>1?r.v.city+' · '+r.v.name+' — ':'')+LABEL[r.x.status]),'wkc-event av-'+r.x.status,'data-venue="'+r.v.id+'" data-day="'+day+'" style="'+sty(r.x.status)+'" title="'+esc0(r.v.name+' · '+LABEL[r.x.status]+(r.x.booking?' · '+r.x.booking.artist:''))+'"');}).join('')+(shown.length>(s.view==='week'?5:3)?button('day','Ещё '+(shown.length-(s.view==='week'?5:3)),'wkc-event wkc-more','data-day="'+day+'"'):'')+(!shown.length?'<span class="av-dayquiet">Нет отмеченных дат</span>':'')+'</div></div>';}).join('')+'</div></div>';}
  function sidebar(list){var v=currentVenue();if(!v)return '';var x=resolve(idx,v.id,s.day,wkDay(0)),r=x.report,b=x.booking;
    var history=entries('reports').filter(function(r){return r.venue===v.id&&r.month===s.day.slice(0,7);}).sort(function(a,b){return b.created.localeCompare(a.created);});
    return '<aside class="wkc-side av-side" aria-label="Даты и договорённости площадки"><div class="wkc-agenda"><h2>'+esc0(fmt(s.day,{weekday:'long',day:'numeric',month:'long'}))+'</h2><div class="wkc-agenda-list">'+list.map(function(vv){var xx=resolve(idx,vv.id,s.day,wkDay(0));return button('slot','<i class="wkc-agenda-dot" aria-hidden="true"></i><span><b>'+esc0(vv.name)+'</b><small>'+esc0(vv.city)+' · '+LABEL[xx.status]+'</small></span>','wkc-agenda-item'+(v.id===vv.id?' on':''),'data-venue="'+vv.id+'" data-day="'+s.day+'" style="'+sty(xx.status)+'"');}).join('')+'</div></div><div class="wkc-detail"><span class="av-badge av-'+x.status+'">'+LABEL[x.status]+'</span><h2>'+esc0(v.name)+'</h2><p class="av-help">'+esc0(v.city)+'</p>'+(r?'<p class="av-help">Ответ от '+esc0(fmt(r.asof,{day:'numeric',month:'long',year:'numeric'}))+' · '+(r.mode==='full'?'весь месяц':'отдельные даты')+'</p><p class="wkc-description">'+esc0([r.contact,r.author,r.note].filter(Boolean).join('\n'))+'</p>':'<p class="av-help">'+(x.status==='recheck'?'После снятия договорённости нужно уточнить доступность.':'Площадка ещё не сообщила доступность этой даты.')+'</p>')+(x.status==='recheck'&&r?'<p class="av-help av-overdue">После снятия договорённости уточните доступность у площадки.</p>':'')+(b?'<div class="av-booking"><b>'+esc0(b.artist)+'</b><p>'+esc0(b.confirmation||'Предварительный резерв')+'</p>'+(b.until?'<p class="'+(x.overdue?'av-overdue':'')+'">'+(x.overdue?'Уточнить резерв · ':'Подтвердить до ')+esc0(fmt(b.until))+'</p>':'')+'<p>'+esc0(b.note)+'</p>'+button('booking','Изменить договорённость','wkc-button','data-id="'+b.id+'"')+'</div>':button('booking','Резерв / бронь','wkc-button primary'))+'<div class="av-side-actions">'+button('report','Записать ответ','wkc-button')+button('request','Запланировать звонок','wkc-button')+'</div>'+(v.phone?'<p class="av-help">'+esc0(v.contact)+'<br>'+esc0(v.phone)+'</p>':'')+'<details class="av-history"><summary>История ответов · '+history.length+'</summary>'+history.map(function(h){return '<div><b>'+esc0(fmt(h.asof))+' · '+(h.mode==='full'?'Весь месяц':'Частично')+(h.void?' · Отменён':'')+'</b><p>Свободно: '+(h.free.join(', ')||'нет')+'</p>'+(h.busy.length?'<p>Занято: '+h.busy.join(', ')+'</p>':'')+'<p>'+esc0([h.contact,h.author,h.note].filter(Boolean).join(' · '))+'</p>'+(!h.void?button('void-report','Отменить ошибочный ответ','pj-plain','data-id="'+h.id+'"'):'')+'</div>';}).join('')+'</details><details class="av-history"><summary>История резервов и броней</summary>'+entries('bookings').filter(function(bk){return bk.venue===v.id&&bk.date===s.day;}).map(function(bk){return '<p>'+esc0(bk.artist)+' · '+(bk.status==='cancelled'?'Снят':LABEL[bk.status])+' · '+esc0(bk.upd.slice(0,10))+'</p>';}).join('')+'</details></div></aside>';
  }
  function requestsView(list){var ids=list.map(function(v){return v.id;}),ms=months(),rows=entries('requests').filter(function(q){return ids.indexOf(q.venue)>=0&&ms.indexOf(q.month)>=0&&(s.req==='all'||q.status!=='answered');}).sort(function(a,b){return (a.next||'9999').localeCompare(b.next||'9999')||a.city.localeCompare(b.city,'ru')||a.month.localeCompare(b.month);});return '<div class="av-summary"><div class="av-summary-head"><h2>Прозвон площадок</h2>'+select('req',[['open','В работе'],['all','Все, включая полученные ответы']],s.req)+button('request','Запланировать прозвон','wkc-button primary')+'</div><p class="av-help">Полный ответ за месяц закрывает ожидающие запросы разных артистов. Частичный ответ оставляет запрос открытым.</p><div class="av-table-scroll"><table class="av-table"><thead><tr><th>Площадка</th><th>Месяц</th><th>Артист / проект</th><th>Состояние</th><th>Следующий звонок</th><th></th></tr></thead><tbody>'+rows.map(function(q){var z=monthStats({id:q.venue},q.month);return '<tr><th>'+esc0(q.city)+'<small>'+esc0(q.venue_name)+'</small></th><td>'+esc0(monthName(q.month))+'<small>'+ (z.latest?'Ответ '+esc0(fmt(z.latest.asof)):'Ответа пока нет')+'</small></td><td>'+esc0(q.artist||'Общий запрос')+'</td><td>'+({call:'Нужно позвонить',waiting:'Ждём ответа',answered:'Ответ получен'})[q.status]+'</td><td class="'+(q.next&&q.next<=wkDay(0)&&q.status!=='answered'?'av-overdue':'')+'">'+esc0(q.next?fmt(q.next):'—')+'</td><td>'+button('request','Открыть','wkc-button','data-id="'+q.id+'"')+button('request-report','Ответ','wkc-button','data-id="'+q.id+'"')+'</td></tr>';}).join('')+'</tbody></table></div>'+(!rows.length?'<p class="av-empty">Открытых запросов за выбранные месяцы нет.</p>':'')+'</div>';}
  function route(){var cities=venues().map(function(v){return v.city;});if(new Set(cities).size!==cities.length)return toast('Для маршрута выберите по одной площадке в каждом городе');var ym=s.anchor.slice(0,7),rows=venues().map(function(v){var z=monthStats(v,ym);return z.free.length?v.city+' — '+v.name+' — '+z.free.join(', '):'';}).filter(Boolean);if(!rows.length)return toast('За этот месяц нет подтверждённых свободных дат для маршрута');S.pl.rp.draft={title:'Свободные даты · '+monthName(ym),month:ym,text:rows.join('\n'),limit:600};S.pl.rp.id=null;goView('route');}
  function renderPage(){init();if(!CAN_SAVE)return head('Свободные даты','Откройте раздел через приложение.');if(!db){if(!loading&&!error)load();return head('Свободные даты','')+'<div class="av-empty">'+esc0(error||'Загружаем площадки и даты…')+(error?button('reload','Повторить','wkc-button'):'')+'</div>';}
    var list=venues();if(list.length&&list.every(function(v){return v.id!==s.venue;}))s.venue=list[0].id;
    var ctx=s.project&&WK.projects[s.project];return '<div class="wkc av'+(s.tab!=='calendar'||!list.length?' av-wide':'')+'"><section class="wkc-main" aria-label="Свободные даты площадок"><header class="wkc-hero"><h1>Свободные даты</h1>'+(ctx?'<p class="av-help">Проект: '+esc0(ctx.title)+' '+button('clear-context','Убрать','pj-plain')+'</p>':'')+'</header><div class="av-tabs" role="tablist">'+[['calendar','Календарь'],['summary','По месяцам'],['requests','Прозвон']].map(function(t){return button('tab',t[1],'av-tab','data-tab="'+t[0]+'" role="tab" aria-selected="'+(s.tab===t[0])+'"');}).join('')+'</div><div class="wkc-toolbar"><h2 class="wkc-month">'+esc0(monthName(s.anchor.slice(0,7)))+'</h2><div class="wkc-controls"><div class="wkc-nav">'+button('prev','‹','','aria-label="Предыдущий период"')+button('today','Сегодня','')+button('next','›','','aria-label="Следующий период"')+'</div>'+button('view',s.view==='week'?'Неделя':'Месяц','wkc-button','aria-label="Вид календаря" aria-haspopup="menu"')+button('filter','Города и площадки'+(list.length?' · '+list.length:''),'wkc-button','aria-haspopup="dialog"')+button('report','+ Записать ответ','wkc-button primary')+'</div></div><div class="av-legend">'+['free','hold','confirmed','busy','unknown','recheck'].map(function(k){return '<span style="'+sty(k)+'"><i></i>'+LABEL[k]+'</span>';}).join('')+button('reload','Обновить','pj-plain')+button('route','В гастрольный маршрут →','pj-plain')+'</div>'+(!list.length?'<div class="av-empty"><h2>Выберите города и площадки</h2><p>Здесь будут общие ответы площадок и ваши договорённости по артистам.</p>'+button('filter','Выбрать площадки','wkc-button primary')+'</div>':s.tab==='calendar'?calendarGrid(list):s.tab==='summary'?summary(list):requestsView(list))+'</section>'+(s.tab==='calendar'&&list.length?sidebar(list):'')+'</div><datalist id="avArtists">'+Array.from(new Set(Object.keys(MYP.projects||{}).map(function(id){return MYP.projects[id].title;}).concat(Object.keys(WK.projects||{}).map(function(id){return WK.projects[id].title;})))).map(function(a){return '<option value="'+esc0(a)+'"></option>';}).join('')+'</datalist>';}
  function open(options){options=options||{};init();s.tab=options.tab||'calendar';if(options.venue){s.venues=[options.venue];s.cities=[];s.venue=options.venue;}if(options.project){s.project=options.project;s.artist=(WK.projects[options.project]||{}).title||'';}if(options.tab)s.tab=options.tab;goView('availability');}
  root.Availability={render:renderPage,open:open,load:load};
  document.addEventListener('click',function(ev){var el=ev.target.closest&&ev.target.closest('[data-av]');if(!el)return;var a=el.getAttribute('data-av');if(a==='open'){open({venue:el.getAttribute('data-venue'),project:el.getAttribute('data-project'),tab:el.getAttribute('data-tab')});return;}if(S.view!=='availability')return;var id=el.getAttribute('data-id');
    if(a==='filter')return picker();if(a==='report')return reportForm();if(a==='booking')return bookingForm(id);if(a==='request')return requestForm(id);if(a==='reload')return load();if(a==='route')return route();if(a==='close')return $('pjDlg').close();if(a==='clear-filter'){var f=el.closest('form');f.querySelectorAll('[type=checkbox]').forEach(function(c){c.checked=false;});filterPicker();return;}
    if(a==='date'){var form=el.closest('form'),name=el.getAttribute('data-name');return wkDateOpen(el,form.elements[name].value,function(iso){form.elements[name].value=iso;el.textContent=iso?fmt(iso,{day:'numeric',month:'short',year:'numeric'}):'Выбрать дату';},el.hasAttribute('data-optional')?[['','Без срока']]:undefined);}
    if(a==='view')return wkPopOpen(el,'wk-menu',button('period','Месяц','wk-menu-item','data-period="month"')+button('period','Неделя','wk-menu-item','data-period="week"'));
    if(a==='period'){s.view=el.getAttribute('data-period');s.tab='calendar';wkPopClose();}
    else if(a==='void-report')return askConfirm('Отменить ошибочный ответ?','Запись останется в истории. Доступность пересчитается по предыдущим ответам.','Отменить ответ',function(){send({op:'void',kind:'reports',id:id,expected:db.reports[id]});});
    else if(a==='request-report'){var q=db.requests[id];s.venue=q.venue;s.anchor=q.month+'-01';s.day=s.anchor;return reportForm();}
    else if(a==='slot'||a==='day'){s.day=el.getAttribute('data-day');if(el.hasAttribute('data-venue'))s.venue=el.getAttribute('data-venue');}
    else if(a==='month-cell'){s.anchor=s.day=el.getAttribute('data-month')+'-01';s.venue=el.getAttribute('data-venue');s.tab='calendar';}
    else if(a==='tab')s.tab=el.getAttribute('data-tab');else if(a==='today')s.anchor=s.day=wkDay(0);else if(a==='prev'||a==='next'){s.anchor=WorkCalendarDates.shift(s.anchor,a==='prev'?-1:1,s.tab==='calendar'&&s.view==='week');s.day=s.anchor;}else if(a==='clear-context'){s.project=s.artist='';}
    render();if((a==='slot'||a==='day')&&innerWidth<=650){var side=document.querySelector('.av-side');if(side)side.scrollIntoView({block:'start',behavior:'smooth'});}
  });
  document.addEventListener('input',function(ev){if(ev.target.closest&&ev.target.closest('[data-av-form="filters"]'))filterPicker();});
  document.addEventListener('change',function(ev){if(ev.target.closest&&ev.target.closest('[data-av-form="filters"]'))return filterPicker();if(S.view!=='availability'||ev.target.closest('dialog'))return;if(ev.target.name==='count'){s.count=+ev.target.value;render();}if(ev.target.name==='req'){s.req=ev.target.value;render();}});
  document.addEventListener('submit',function(ev){var f=ev.target;if(!f.matches('[data-av-form]'))return;ev.preventDefault();var kind=f.getAttribute('data-av-form');if(kind==='filters'){s.anchor=s.day=f.elements.anchor.value+'-01';s.count=+f.elements.count.value;s.cities=Array.from(f.querySelectorAll('[name=cities]:checked')).map(function(c){return c.value;});s.venues=Array.from(f.querySelectorAll('[name=venues]:checked')).filter(function(c){return !s.cities.length||s.cities.indexOf(c.closest('[data-city]').getAttribute('data-city'))>=0;}).map(function(c){return c.value;});try{localStorage.setItem(prefKey,JSON.stringify({cities:s.cities,venues:s.venues}));}catch(e){}$('pjDlg').close();render();return;}
    var d={},id=f.getAttribute('data-id');new FormData(f).forEach(function(v,k){d[k]=v;});try{var op={op:'put',kind:kind,data:d};if(id){op.id=id;op.expected=f._expected;}if(kind==='reports'){d.free=parseDays(d.free,d.month);d.busy=parseDays(d.busy,d.month);}if(kind==='requests'&&!id){if(d.to<d.from)throw new Error('Последний месяц должен быть не раньше первого');var ms=[],m=d.from;while(m<=d.to&&ms.length<=12){ms.push(m);m=monthShift(m,1);}if(ms.length>12)throw new Error('За один раз можно запросить до 12 месяцев');op.op='request_batch';op.venues=venues().map(function(v){return v.id;});op.months=ms;}send(op,f,function(){if(kind==='reports'){s.venue=d.venue;s.anchor=d.month+'-01';s.day=d.month+'-'+pad(d.free[0]||1);}else if(kind==='bookings'){s.venue=d.venue;s.anchor=s.day=d.date;}else{s.tab='requests';}});}catch(e){f.querySelector('.av-error').textContent=e.message;}
  });
